#!/usr/bin/env node
import {spawn} from "node:child_process";import {mkdir,writeFile} from "node:fs/promises";import path from "node:path";import {fileURLToPath} from "node:url";
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"../../../../"),target=path.resolve(process.argv[2]||path.join(root,"evidence/runtime/response.json")),child=spawn(process.execPath,[path.join(root,"app.mjs")],{cwd:root,stdio:["ignore","pipe","inherit"]});let done=false;const fail=e=>{if(!done){done=true;child.kill();console.error(e);process.exitCode=1;}};child.stdout.once("data",async chunk=>{try{const {port}=JSON.parse(String(chunk).trim()),response=await fetch(`http://127.0.0.1:${port}/`),body=await response.text(),evidence={action:"GET /",status:response.status,body};await mkdir(path.dirname(target),{recursive:true});await writeFile(target,`${JSON.stringify(evidence,null,2)}\n`);done=true;child.kill();if(response.status!==200||body!=="hello from fixture")throw new Error("unexpected response");console.log(JSON.stringify(evidence));}catch(e){fail(e.stack||e.message);}});child.on("error",e=>fail(e.message));setTimeout(()=>fail("verification timeout"),5000).unref();
